'use strict';
(() => {
  // Token is generated by the trusted parent for this exact frame instance.
  const token = document.currentScript.dataset.translationToken;
  const core = window.InkwellTranslationCore;
  let pending = null;
  const send = (data) => parent.postMessage({ ...data, type: 'inkwell-translation', token }, '*');
  document.addEventListener('contextmenu', (event) => {
    const snapshot = core.capture(document.querySelector('#inkwell-mail-body'));
    if (!snapshot) return;
    event.preventDefault();
    pending = { ...snapshot, id: window.InkwellTranslationCore.uuid() };
    send({
      action: 'selection',
      id: pending.id,
      text: pending.text,
      x: event.clientX,
      y: event.clientY,
    });
  });
  window.addEventListener('message', (event) => {
    const data = event.data;
    if (
      event.source !== parent ||
      data?.type !== 'inkwell-translation' ||
      data.token !== token ||
      data.action !== 'apply' ||
      !pending ||
      data.id !== pending.id ||
      typeof data.translation !== 'string' ||
      data.translation.length > 16000 ||
      typeof data.language !== 'string'
    )
      return;
    const applied = core.insert(pending, data.translation, data.language);
    send({ action: 'applied', id: pending.id, applied });
    pending = null;
  });
})();
